const body = $input.first().json.body || {};
let rawCsv = body.csv || '';
let watchTime = body.averageWatchTime || '6.8s';
let completionRate = body.completionRate || '41.2%';
let dropoffAt2s = body.dropoffAt2s || '38.4%';
let views = body.views || '2.4M';

if (rawCsv && rawCsv.includes(',')) {
  // Quick CSV line parser if user uploaded raw CSV string
  const lines = rawCsv.split('\n');
  if (lines.length > 1) {
    const headers = lines[0].toLowerCase().split(',');
    const firstRow = lines[1].split(',');
    headers.forEach((h, idx) => {
      if (h.includes('watch') || h.includes('tempo')) watchTime = firstRow[idx] || watchTime;
      if (h.includes('completion') || h.includes('conclus')) completionRate = firstRow[idx] || completionRate;
      if (h.includes('drop') || h.includes('queda')) dropoffAt2s = firstRow[idx] || dropoffAt2s;
      if (h.includes('view') || h.includes('visitas')) views = firstRow[idx] || views;
    });
  }
}

const metricsSummary = `Tempo Médio Assistido: ${watchTime}, Taxa de Conclusão: ${completionRate}, Queda nos Primeiros 2s: ${dropoffAt2s}, Visualizações: ${views}`;

return [{
  json: {
    watchTime,
    completionRate,
    dropoffAt2s,
    views,
    metricsSummary
  }
}];

